#include <linux/uaccess.h>
#include <linux/bitmap.h>

int compat_sys_mbind(int mode, compat_ulong_t __user *nmask, compat_ulong_t maxnode) {
    int err;
    unsigned long *bitmap = NULL;
    unsigned long nbits = maxnode;
    unsigned long size;

    if (!nmask || maxnode == 0)
        return -EINVAL;

    size = (nbits + 7) / 8; // Calculate size in bytes
    bitmap = kmalloc(size, GFP_KERNEL);
    if (!bitmap)
        return -ENOMEM;

    if (copy_from_user(bitmap, nmask, size)) {
        err = -EFAULT;
        goto out;
    }

    err = sys_mbind(mode, nmask, bitmap, nbits, NULL, 0);

out:
    kfree(bitmap);
    return err;
}

int compat_sys_mbind(int mode, compat_ulong_t __user *nmask, compat_ulong_t maxnode) {
    int err = 0;
    unsigned long nbits = maxnode;
    unsigned long size = BITS_TO_LONGS(nbits) * sizeof(unsigned long);
    unsigned long *bitmap = NULL;

    if (nmask) {
        bitmap = compat_alloc_user_space(size);
        if (copy_from_user(bitmap, nmask, size)) {
            err = -EFAULT;
            goto out;
        }
    }

    err = sys_mbind(mode, bitmap, nbits);

out:
    return err;
}

#include <linux/syscalls.h>
#include <linux/uaccess.h>
#include <linux/bitmap.h>

SYSCALL_DEFINE3(set_mempolicy_compat, int, mode, compat_ulong_t __user *, nmask, compat_ulong_t, maxnode)
{
    unsigned long *bitmap = NULL;
    int err = 0;
    unsigned int bits = maxnode;
    unsigned int size = BITS_TO_LONGS(maxnode) * sizeof(long);

    if (nmask) {
        bitmap = compat_alloc_user_space(size);
        if (!access_ok(nmask, size)) {
            return -EFAULT;
        }
        if (copy_from_user(bitmap, nmask, size)) {
            return -EFAULT;
        }
    }

    err = do_set_mempolicy(mode, bitmap, bits);

    if (nmask && bitmap) {
        if (copy_to_user(nmask, bitmap, size)) {
            return -EFAULT;
        }
    }

    return err;
}

int compat_sys_mempolicy(int mode, compat_ulong_t __user *nmask, compat_ulong_t maxnode)
{
    int err;
    unsigned long *bmp = NULL;
    unsigned long bits;
    unsigned long sz;
    compat_ulong_t maxnode_val = maxnode;

    if (maxnode_val == 0) {
        return -EINVAL;
    }

    bits = maxnode_val;
    sz = (bits + BITS_PER_LONG - 1) / BITS_PER_LONG;

    if (nmask) {
        bmp = compat_alloc_user_space(sz * sizeof(long));
        if (bmp == NULL) {
            return -EFAULT;
        }

        if (copy_from_user(bmp, nmask, sz * sizeof(compat_ulong_t))) {
            return -EFAULT;
        }
    }

    err = do_mempolicy(mode, bmp, bits);
    return err;
}

#include <linux/syscalls.h>
#include <linux/uaccess.h>
#include <linux/bitmap.h>

SYSCALL_DEFINE3(set_mempolicy, int, mode, compat_ulong_t __user *, nmask,
                compat_ulong_t, maxnode)
{
    unsigned long *bmp = NULL;
    unsigned int nbits = maxnode;
    int err = 0;

    if (nmask) {
        compat_ulong_t *ubmp;
        unsigned int len = COMPAT_BITMAP_SIZE(maxnode);

        ubmp = compat_alloc_user_space(len);
        if (copy_from_user(ubmp, nmask, len))
            return -EFAULT;

        bmp = compat_alloc_user_space(bitmap_size(nbits));
        if (!bmp)
            return -ENOMEM;

        if (compat_user_bitmap_to_native(ubmp, bmp, nbits))
            return -EFAULT;
    }

    err = do_set_mempolicy(mode, bmp, nbits);

    if (bmp && nmask)
        compat_user_native_to_bitmap(bmp, nmask, nbits);

    return err;
}
